sys_variable_value.value:
// ATF injects assertEqual, steps, outputs, stepResult and an enclosing try block - bare body.
// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var productId = steps("c794da2ea5a641529d7bf7bce9844411").record_id;
if (!productId || ('' + productId).length !== 32) {
    throw new Error('unresolved step reference for productId: ' + productId);
}
var calc = new x_2298436_snackf_0.SnackFlowCalc();

// The refused dispatch must have left no trace and no balance change.
assertEqual({ name: 'balance unchanged after refused dispatch', shouldbe: 75, value: calc.ledgerBalance('finished_product', productId, null) });

var rejected = new GlideAggregate('x_2298436_snackf_0_stock_transaction');
rejected.addQuery('product', productId);
rejected.addQuery('quantity', 1000);
rejected.addAggregate('COUNT');
rejected.query();
var cnt = rejected.next() ? parseInt(rejected.getAggregate('COUNT'), 10) : 0;
assertEqual({ name: 'no ledger row written for the refused dispatch', shouldbe: 0, value: cnt });

var sb = new GlideRecord('x_2298436_snackf_0_stock_bal');
sb.addQuery('product', productId);
sb.query();
var stored = sb.next() ? parseFloat(sb.getValue('current_balance')) : -1;
assertEqual({ name: 'stock_bal still 75 after refusal', shouldbe: 75, value: stored });

stepResult.setOutputMessage('after refusal: ledger=75 stock_bal=' + stored + ' rejected_rows=' + cnt);
